function [m] = damp_dipole(w, b, k)
%DAMP_DIPOLE  The dipole that makes it for the coils, (k/|B|) (e x b) with b the unit field (the detumble law's sign: the torque
%   -k e perpendicular to the field).
%   w: real[1][3] (passed a plain number)
%   b: real[1][3] (passed a plain number)
%   k: real[1] (passed a plain number)
%   returns m: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 1);
    m = zeros(3, 1);
    bn = sqrt(b(1)*b(1) + b(2)*b(2) + b(3)*b(3));
    if (bn > 1e-9)
        h__90 = asils.alg.steplaws.damp_excess(w);
        h__91 = (b / bn);
        m = ([h__90(2)*h__91(3) - h__90(3)*h__91(2); h__90(3)*h__91(1) - h__90(1)*h__91(3); h__90(1)*h__91(2) - h__90(2)*h__91(1)] * (k / bn));
    end
end
